class DocPDF(FPDF):
    def footer(self) -> None:
        self.set_y(-12)
        self.set_font("cn", "", 9)
        self.cell(0, 8, f"\u7b2c {self.page_no()} \u9875", align="C")


def main() -> None:
    project_root = Path(__file__).resolve().parents[1]
    font = find_cn_font()
    blocks = build_blocks(project_root)

    pdf = DocPDF(unit="mm", format="A4")
    pdf.set_auto_page_break(auto=True, margin=18)
    pdf.add_font("cn", "", str(font))
    pdf.set_font("cn", "", 11)

    l_margin, t_margin, r_margin = 18, 18, 18
    pdf.set_margins(l_margin, t_margin, r_margin)
    text_w = 210 - l_margin - r_margin

    for level, text in blocks:
        if level == "title":
            pdf.add_page()
            pdf.set_font("cn", "", 22)
            pdf.multi_cell(text_w, 12, text, align="C")
            continue
        if level == "subtitle":
            pdf.set_font("cn", "", 14)
            pdf.multi_cell(text_w, 9, text, align="C")
            pdf.ln(6)
            continue
        if level == "h1":
            pdf.add_page()
            pdf.set_font("cn", "", 15)
            pdf.multi_cell(text_w, 8, text, align="L")
            pdf.ln(2)
            continue
        if level == "h2":
            pdf.set_font("cn", "", 12)
            pdf.multi_cell(text_w, 7, text, align="L")
            pdf.ln(1)
            continue
        if level == "p":
            pdf.set_font("cn", "", 10.5)
            pdf.multi_cell(text_w, 5.6, text, align="J")
            pdf.ln(1.5)
            if pdf.page_no() > MAX_PAGES:
                raise SystemExit(f"Exceeded MAX_PAGES={MAX_PAGES}, shorten build_blocks().")

    out = project_root / OUTPUT_REL
    pdf.output(str(out))
    n = pdf.page_no()
    print("Generated:", out)
    print("Pages:", n, "(limit", MAX_PAGES, ")")


if __name__ == "__main__":
    main()
